import { FC } from 'react';

interface UploadFile {
    /** 文件唯一标识 */
    uid: string;
    /** 文件名 */
    name?: string;
    /** 文件地址 */
    url?: string;
    /** 原始文件对象 */
    raw?: any;
    /** 文件大小 (KB) */
    size?: number;
    /** 文件状态 */
    status?: 'uploading' | 'done' | 'error';
    /** 上传进度 */
    percent?: number;
    /** 错误信息 */
    message?: string;
}
interface UploadProps {
    /** 文件列表 (受控) */
    fileList?: UploadFile[];
    /** 默认文件列表 (非受控) */
    defaultFileList?: UploadFile[];
    /** 接受的文件类型 */
    accept?: 'image' | 'video' | 'all';
    /** 最大上传数量 */
    maxCount?: number;
    /** 最大文件大小 (KB) */
    maxSize?: number;
    /** 是否多选 */
    multiple?: boolean;
    /** 是否禁用 */
    disabled?: boolean;
    /** 是否可预览 */
    preview?: boolean;
    /** 是否可删除 */
    deletable?: boolean;
    /** 上传地址 */
    url?: string;
    /** 上传请求头 */
    headers?: Record<string, string>;
    /** 上传额外参数 */
    data?: Record<string, any>;
    /** 上传文件字段名 */
    name?: string;
    /** 自定义上传 */
    customUpload?: (file: any) => Promise<string>;
    /** 文件列表变化回调 */
    onChange?: (fileList: UploadFile[]) => void;
    /** 上传前回调 */
    onBeforeUpload?: (file: any) => boolean | Promise<boolean>;
    /** 删除回调 */
    onRemove?: (file: UploadFile, index: number) => boolean | Promise<boolean>;
    /** 预览回调 */
    onPreview?: (file: UploadFile) => void;
    /** 自定义类名 */
    className?: string;
}

declare const Upload: FC<UploadProps>;

export { Upload, Upload as default };
export type { UploadFile, UploadProps };
